#[test]
fn secret_value() {
    let v = SecretValue::from("top-secret-1").with_version("3");
    assert_eq!(v.reveal().unwrap(), "top-secret-1");
    assert_eq!(v.reveal_bytes(), b"top-secret-1");
    assert_eq!(v.version(), Some("3"));
    assert_eq!(v.len(), 12);
    assert!(!v.is_empty());
    for text in [
        format!("{v:?}"),
        format!("{v}"),
        serde_json::to_string(&v).unwrap(),
    ] {
        assert!(text.contains("SecretValue([REDACTED])"));
        assert!(!text.contains("top-secret-1"));
    }
    let bin = SecretValue::from(vec![0xff, 0x00]);
    assert_eq!(bin.reveal().unwrap_err().code(), ErrorCode::Validation);
    assert_eq!(
        bin.json::<serde_json::Value>().unwrap_err().code(),
        ErrorCode::Validation
    );
    let j = SecretValue::from(r#"{"a":1}"#.to_owned());
    assert_eq!(j.json::<serde_json::Value>().unwrap(), json!({"a": 1}));
    assert_ne!(j.sha256(), bin.sha256());
    assert!(SecretValue::new(Vec::new()).is_empty());

    assert_eq!(SecretData::from("a").into_bytes().unwrap(), b"a");
    assert_eq!(SecretData::from("a".to_owned()).into_bytes().unwrap(), b"a");
    assert_eq!(SecretData::from(vec![1u8]).into_bytes().unwrap(), vec![1]);
    assert_eq!(SecretData::from(&b"b"[..]).into_bytes().unwrap(), b"b");
    assert_eq!(
        SecretData::from(json!({"k": 1})).into_bytes().unwrap(),
        br#"{"k":1}"#
    );
    assert_eq!(
        format!("{:?}", SecretData::from("hidden-value")),
        "SecretData([REDACTED])"
    );
}

#[test]
fn metadata_json_and_time() {
    let t = SystemTime::UNIX_EPOCH + Duration::from_millis(1_700_000_000_123);
    assert_eq!(rfc3339(t), "2023-11-14T22:13:20.123Z");
    assert_eq!(rfc3339(SystemTime::UNIX_EPOCH), "1970-01-01T00:00:00.000Z");
    assert_eq!(
        rfc3339(SystemTime::UNIX_EPOCH + Duration::from_secs(951_782_400)),
        "2000-02-29T00:00:00.000Z"
    );
    let mut m = SecretMetadata::new("app/db");
    m.path = Some("app/".into());
    m.version = Some("2".into());
    m.created_at = Some(t);
    m.updated_at = Some(t);
    m.versions = Some(2);
    m.tags.insert("env".into(), "prod".into());
    let j = m.to_json();
    assert_eq!(j["name"], "app/db");
    assert_eq!(j["path"], "app/");
    assert_eq!(j["version"], "2");
    assert_eq!(j["createdAt"], "2023-11-14T22:13:20.123Z");
    assert_eq!(j["updatedAt"], "2023-11-14T22:13:20.123Z");
    assert_eq!(j["versions"], 2);
    assert_eq!(j["tags"]["env"], "prod");
    assert_eq!(
        SecretMetadata::new("x").to_json(),
        json!({"name": "x", "tags": {}, "extra": {}})
    );
}

#[test]
fn secret_map() {
    let mut m = SecretMap::new();
    assert!(m.is_empty());
    m.push("b", SecretValue::from("1"));
    m.push("a", SecretValue::from("2"));
    assert_eq!(m.len(), 2);
    assert_eq!(m.names().collect::<Vec<_>>(), vec!["b", "a"]);
    assert_eq!(m.get("a").unwrap().reveal().unwrap(), "2");
    assert!(m.get("c").is_none());
    assert_eq!(m.iter().count(), 2);
    assert!(
        !format!("{m:?}").contains('1'.to_string().as_str())
            || format!("{m:?}").contains("REDACTED")
    );
    let collected: SecretMap = m.clone().into_iter().collect();
    assert_eq!(collected, m);
}

#[tokio::test]
async fn provider_defaults_on_memory_store() {
    let p = InMemorySecretsProvider::new()
        .with_secret("app/text", "hello")
        .with_secret("app/num", " 42.5 ")
        .with_secret("app/bool", "On")
        .with_secret("app/json", r#"{"a":[1,2]}"#)
        .with_secret("app/bin", vec![0xffu8, 0xfe])
        .with_secret("app/sub/deep", "x");
    assert_eq!(p.len(), 6);
    assert!(!p.is_empty());
    assert!(format!("{p:?}").contains("InMemorySecretsProvider"));

    assert_eq!(
        p.get_string("app/text", None).await.unwrap().as_deref(),
        Some("hello")
    );
    assert_eq!(p.get_number("app/num", None).await.unwrap(), Some(42.5));
    assert_eq!(p.get_bool("app/bool", None).await.unwrap(), Some(true));
    assert_eq!(
        p.get_json("app/json", None).await.unwrap(),
        Some(json!({"a": [1, 2]}))
    );
    for name in ["app/text"] {
        assert_eq!(
            p.get_number(name, None).await.unwrap_err().code(),
            ErrorCode::Validation
        );
        assert_eq!(
            p.get_bool(name, None).await.unwrap_err().code(),
            ErrorCode::Validation
        );
        assert_eq!(
            p.get_json(name, None).await.unwrap_err().code(),
            ErrorCode::Validation
        );
    }
    let err = p.get_string("app/bin", None).await.unwrap_err();
    assert_eq!(err.code(), ErrorCode::Validation);
    assert!(err.message().contains("app/bin"));
    for missing in [
        p.get_string("nope", None).await.unwrap().is_none(),
        p.get_json("nope", None).await.unwrap().is_none(),
        p.get_number("nope", None).await.unwrap().is_none(),
        p.get_bool("nope", None).await.unwrap().is_none(),
        !p.exists("nope", None).await.unwrap(),
        p.metadata("nope", None).await.unwrap().is_none(),
    ] {
        assert!(missing);
    }
    assert_eq!(
        p.require("nope", None).await.unwrap_err().code(),
        ErrorCode::NotFound
    );
    assert_eq!(
        p.require("app/text", None).await.unwrap().version(),
        Some("1")
    );
    assert!(p.exists("app/text", None).await.unwrap());
    assert_eq!(
        p.get("", None).await.unwrap_err().code(),
        ErrorCode::Validation
    );
    assert_eq!(
        p.set(" ", "x".into(), None).await.unwrap_err().code(),
        ErrorCode::Validation
    );
    assert_eq!(
        p.delete("", None).await.unwrap_err().code(),
        ErrorCode::Validation
    );
    assert_eq!(
        p.metadata("", None).await.unwrap_err().code(),
        ErrorCode::Validation
    );

    let many = p
        .get_many(&["app/num", "nope", "app/text"], None)
        .await
        .unwrap();
    assert_eq!(
        many.names().collect::<Vec<_>>(),
        vec!["app/num", "app/text"]
    );

    let all = p.get_all(Some("app/")).await.unwrap();
    assert_eq!(
        all.names().collect::<Vec<_>>(),
        vec!["app/bin", "app/bool", "app/json", "app/num", "app/text"]
    );
    let listed = p.list(Some("app/")).await.unwrap();
    assert_eq!(listed.len(), 5);
    assert!(listed.windows(2).all(|w| w[0].name <= w[1].name));
    assert_eq!(listed[0].path.as_deref(), Some("app/"));
    assert_eq!(p.list(None).await.unwrap().len(), 0, "no top-level names");
    assert_eq!(p.get_all(Some("app/sub/")).await.unwrap().len(), 1);

    // versions, CAS, tags, description, delete versions
    let v2 = p
        .set(
            "app/text",
            "hello2".into(),
            Some(&SetOptions {
                cas: Some(1),
                ..SetOptions::default()
            }),
        )
        .await
        .unwrap();
    assert_eq!(v2, "2");
    let err = p
        .set(
            "app/text",
            "x".into(),
            Some(&SetOptions {
                cas: Some(1),
                ..SetOptions::default()
            }),
        )
        .await
        .unwrap_err();
    assert_eq!(err.code(), ErrorCode::Conflict);
    let mut tags = BTreeMap::new();
    tags.insert("team".to_owned(), "core".to_owned());
    let opts = SetOptions {
        tags,
        description: Some("d".into()),
        cas: Some(0),
        path: None,
    };
    assert_eq!(
        p.set("new", json!({"k": true}).into(), Some(&opts))
            .await
            .unwrap(),
        "1"
    );
    let meta = p.metadata("new", None).await.unwrap().unwrap();
    assert_eq!(meta.tags["team"], "core");
    assert_eq!(meta.extra["description"], "d");
    assert_eq!(meta.versions, Some(1));
    assert!(meta.path.is_none());
    let old = GetOptions {
        version: Some("1".into()),
        path: None,
    };
    assert_eq!(
        p.get_string("app/text", Some(&old))
            .await
            .unwrap()
            .as_deref(),
        Some("hello")
    );
    let gone = GetOptions {
        version: Some("9".into()),
        path: None,
    };
    assert!(p.get("app/text", Some(&gone)).await.unwrap().is_none());
    let bad = GetOptions {
        version: Some("x".into()),
        path: None,
    };
    assert_eq!(
        p.get("app/text", Some(&bad)).await.unwrap_err().code(),
        ErrorCode::Validation
    );
    let del_v1 = DeleteOptions {
        versions: vec!["1".into()],
        ..DeleteOptions::default()
    };
    p.delete("app/text", Some(&del_v1)).await.unwrap();
    assert_eq!(
        p.get_string("app/text", None).await.unwrap().as_deref(),
        Some("hello2")
    );
    let del_bad = DeleteOptions {
        versions: vec!["x".into()],
        ..DeleteOptions::default()
    };
    assert_eq!(
        p.delete("app/text", Some(&del_bad))
            .await
            .unwrap_err()
            .code(),
        ErrorCode::Validation
    );
    let del_v2 = DeleteOptions {
        versions: vec!["2".into()],
        permanent: true,
        path: None,
    };
    p.delete("app/text", Some(&del_v2)).await.unwrap();
    assert!(!p.exists("app/text", None).await.unwrap());
    assert_eq!(
        p.delete("app/text", None).await.unwrap_err().code(),
        ErrorCode::NotFound
    );
    p.delete("new", None).await.unwrap();

    // error injection
    p.fail_next(Error::unavailable("boom"));
    assert_eq!(
        p.get("app/num", None).await.unwrap_err().code(),
        ErrorCode::Unavailable
    );
    p.fail_next(Error::unavailable("boom"));
    assert!(p.get_all(Some("app/")).await.is_err());
    assert!(p.calls() > 10);
    assert!(p.remove("app/num"));
    assert!(!p.remove("app/num"));
    assert!(p.insert("fresh", "1") == 1);
}

#[tokio::test]
async fn unversioned_store() {
    let p = InMemorySecretsProvider::unversioned();
    assert!(p.is_empty());
    assert_eq!(p.set("a", "1".into(), None).await.unwrap(), "");
    assert_eq!(p.set("a", "2".into(), None).await.unwrap(), "");
    let v = p.get("a", None).await.unwrap().unwrap();
    assert_eq!(v.version(), None);
    assert_eq!(v.reveal().unwrap(), "2");
    let m = p.metadata("a", None).await.unwrap().unwrap();
    assert_eq!((m.version, m.versions), (None, None));
}

#[tokio::test]
async fn load_env_modes() {
    let p = InMemorySecretsProvider::new()
        .with_secret("cfg/db-url", "postgres://x")
        .with_secret("cfg/api.key", "k")
        .with_secret("cfg/bin", vec![0xffu8]);
    assert_eq!(env_var_name("APP_", "db-url.v2"), "APP_DB_URL_V2");

    let mut sink: HashMap<String, String> = HashMap::new();
    sink.insert("APP_API_KEY".into(), "existing".into());
    let p2 = InMemorySecretsProvider::new()
        .with_secret("cfg/db-url", "postgres://x")
        .with_secret("cfg/api.key", "k");
    let opts = LoadEnvOptions {
        override_existing: false,
        prefix: "APP_".into(),
    };
    let set = load_env_into(&p2, &EnvSource::from("cfg/"), &opts, &mut sink)
        .await
        .unwrap();
    assert_eq!(set.len(), 1);
    assert_eq!(set["APP_DB_URL"], "cfg/db-url");
    assert_eq!(
        EnvSink::get(&sink, "APP_API_KEY").as_deref(),
        Some("existing")
    );
    let opts = LoadEnvOptions {
        override_existing: true,
        prefix: "APP_".into(),
    };
    let set = load_env_into(&p2, &EnvSource::from("cfg/".to_owned()), &opts, &mut sink)
        .await
        .unwrap();
    assert_eq!(set.len(), 2);
    assert_eq!(sink["APP_API_KEY"], "k");

    // non-UTF-8 value in path mode
    let err = load_env_into(
        &p,
        &EnvSource::from("cfg/"),
        &LoadEnvOptions::default(),
        &mut sink,
    )
    .await
    .unwrap_err();
    assert_eq!(err.code(), ErrorCode::Validation);
    assert!(!err.message().contains('\u{fffd}'));

    // mapping mode
    let mapping: EnvSource = [("DATABASE_URL", "cfg/db-url")].into_iter().collect();
    let set = load_env_into(&p, &mapping, &LoadEnvOptions::default(), &mut sink)
        .await
        .unwrap();
    assert_eq!(set["DATABASE_URL"], "cfg/db-url");
    assert_eq!(sink["DATABASE_URL"], "postgres://x");
    let missing: EnvSource = [("X", "cfg/none")].into_iter().collect();
    let err = load_env_into(&p, &missing, &LoadEnvOptions::default(), &mut sink)
        .await
        .unwrap_err();
    assert_eq!(err.code(), ErrorCode::NotFound);
    let binary: EnvSource = [("B", "cfg/bin")].into_iter().collect();
    assert_eq!(
        load_env_into(&p, &binary, &LoadEnvOptions::default(), &mut sink)
            .await
            .unwrap_err()
            .code(),
        ErrorCode::Validation
    );

    // empty path = root
    let root = InMemorySecretsProvider::new().with_secret("top", "1");
    let set = load_env_into(
        &root,
        &EnvSource::Path(String::new()),
        &LoadEnvOptions::default(),
        &mut sink,
    )
    .await
    .unwrap();
    assert_eq!(set["TOP"], "top");

    // process environment (unique names)
    let unique = format!("GROWTEST_{}_", std::process::id());
    let opts = LoadEnvOptions {
        override_existing: false,
        prefix: unique.clone(),
    };
    let arc: Arc<dyn SecretsProvider> = Arc::new(root);
    let set = arc.load_env(&EnvSource::from(""), &opts).await.unwrap();
    assert_eq!(std::env::var(format!("{unique}TOP")).unwrap(), "1");
    assert_eq!(set.len(), 1);
    assert_eq!(
        ProcessEnv.get(&format!("{unique}TOP")).as_deref(),
        Some("1")
    );
}
